INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6010596, 879756, 83313, '<td valign="top">''Tis the fate of abstract photography in a non abstract challenge. When I enter something of this nature, my success is measured in the comments and in appealing strongly to a narrow audience. I gave it an 8.</td>', '''Tis the fate of abstract photography in a non abstract challenge. When I enter something of this nature, my success is measured in the comments and in appealing strongly to a narrow audience. I gave it an 8.', '2010-05-17 02:47:48.000000', NULL, 0),
(6010597, 879709, 82707, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by Jutilda:</b></div><hr/><i> Aboriginal?  I hope the average person gets that.  What a beautiful child.  Love the lighting and perfect focus. </i></td></tr></table> <br/>Thank you <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21_F.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21_F.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21_F.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=15711" rel="nofollow" target="_blank">Jutilda</a>! ...You''ve restored my faith in my own judgment!  A lot of people did get it, but many others didn''t, which was reflected in the scores..... I wonder if the 3 (1 voters) left a comment.  Somehow I doubt it.  :)</td>', 'Originally posted by Jutilda: Aboriginal?  I hope the average person gets that.  What a beautiful child.  Love the lighting and perfect focus.  Thank you  Jutilda! ...You''ve restored my faith in my own judgment!  A lot of people did get it, but many others didn''t, which was reflected in the scores..... I wonder if the 3 (1 voters) left a comment.  Somehow I doubt it.  :)', '2010-05-17 02:48:10.000000', NULL, 0),
(6010600, 879616, 83313, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by cowboy221977:</b></div><hr/><i> OK besides the title....I don''t know how this meets the challenge. </i></td></tr></table> <br/> <br/>Allsorts is the name of <a href="//ozbo.com/Bassett-s-Candy-Allsorts-Licorice-41317-ozbo.html" rel="nofollow" target="_blank">this candy.</a></td>', 'Originally posted by cowboy221977: OK besides the title....I don''t know how this meets the challenge.   Allsorts is the name of this candy.', '2010-05-17 02:50:49.000000', NULL, 0),
(6010615, 879261, 97225, '<td valign="top">This is really cool and interesting and not achieved by the methods I imagined at all. (I was thinking a distorted reflection). I''m sorry that your efforts and ingenuity were not better rewarded, but I am going to take inspiration from your creativity and give this a try.  Thank you for the detailed information.<br/>I have nominated this in the posthumous underappreciated thread.<br/><br/><i>Message edited by author 2010-05-17 02:23:24.</i></td>', 'This is really cool and interesting and not achieved by the methods I imagined at all. (I was thinking a distorted reflection). I''m sorry that your efforts and ingenuity were not better rewarded, but I am going to take inspiration from your creativity and give this a try.  Thank you for the detailed information.I have nominated this in the posthumous underappreciated thread.', '2010-05-17 03:10:45.000000', '2010-05-17 03:23:24.000000', 0),
